        ls[task_id] = lf[task_id] - task.duration

    # Calculate Slack and Critical Path
    slack = {task_id: ls[task_id] - es[task_id] for task_id in sorted_tasks}
    critical_path = [task_id for task_id in sorted_tasks if slack[task_id] == 0]

